function renderLibrary(main){main.append(heading('АЛЬФА-БАНК · ЭКСПЕРТНЫЙ ВЗГЛЯД','Позиция банка — отдельный слой','Сохраняем авторство, дату и различие между оценкой, прогнозом и фактом.'));main.append(banner('В прототипе включены три выбранных утверждения страницы 1 обзора от 11 сентября 2026. Полный корпус из девяти PDF ещё не размечен.','neutral'));const grid=el('div','three-grid');for(const claim of S.library.claims){const doc=S.library.documents.find(d=>d.document_id===claim.document_id),c=card('bank-library-card');append(c,pill(claim.claim_type==='FORECAST'?'ПРОГНОЗ БАНКА':'ОЦЕНКА БАНКА',claim.claim_type==='FORECAST'?'amber':'red'),el('h3','',claim.text),text(claim.modality_raw||'Альфа-Банк'),el('p','meta',date(doc?.published_at)+' · страница 1'),button('Посмотреть фрагмент',()=>showLibraryClaim(claim),'text-button','external'));grid.append(c);}main.append(grid,qualityNote('Разметка ожидает человеческой проверки. Исторический прогноз не превращается в актуальный факт или обещание результата.'));}
function renderHistory(main){main.append(heading('СОХРАНЁННЫЙ КОНТЕКСТ','История разборов','Версия профиля и исходные основания фиксируются для каждого запуска.',[button('Новый разбор',startRun,'button primary','plus')]));const c=card();if(!S.history.length)c.append(empty('Разборов пока нет','Запустите анализ события. Здесь сохранится его результат и версия профиля.'));for(const item of S.history){const row=el('div','history-row');append(row,icon('pulse'),append(el('div','history-label'),el('h3','','Ставка и условия финансирования'),el('small','',shortDate(item.created_at))),pill({SUCCEEDED:'Готово',PARTIAL:'С пробелами',RUNNING:'В работе',QUEUED:'В очереди',FAILED:'Не опубликован',WAITING_INPUT:'Уточнение',CANCELLED:'Остановлен',DEFERRED_BUDGET:'Лимит API'}[item.status]||item.status),button('Открыть',()=>openRun(item.id),'button small','arrow'));c.append(row);}main.append(c);}
async function showSources(refs,fromRun=false){let ctx=S.snapshot;if(fromRun&&S.run){if(!S.runSources)S.runSources=await api(`/api/runs/${S.run.run_id}/sources`);ctx=S.runSources;}const content=$('#source-content');content.replaceChildren();const evMap=new Map([...(ctx.evidence||[]),...(S.library?.evidence||[])].map(e=>[e.evidence_id,e])),docMap=new Map([...(ctx.documents||[]),...(S.library?.documents||[])].map(d=>[d.document_id,d]));let ids=[];if(refs){for(const ref of refs){if(ref.kind==='evidence')ids.push(ref.ref_id);else if(ref.kind==='feature'){const f=ctx.profile.features.find(f=>f.feature_id===ref.ref_id);if(f)ids.push(...f.source_refs.filter(c=>c.kind==='evidence').map(c=>c.ref_id));}else if(ref.kind==='calculation'){const record=ctx.calculations?.find(c=>c.calculation_id===ref.ref_id);if(record){const item=el('div','source-item');append(item,el('h3','','Формула условной чувствительности'),text('Остаток плавающего долга × шаг ставки / 100 × дни / база дней'),text(`${format(record.inputs.principal_rub)} × ${format(record.inputs.delta_rate_pp)} / 100 × ${record.inputs.horizon_days} / ${record.inputs.day_count_basis}`),text(record.inputs.assumptions.join(' ')));content.append(item);ids.push(...record.inputs.principal_refs.flatMap(r=>ctx.profile.features.find(f=>f.feature_id===r.ref_id)?.source_refs.map(c=>c.ref_id)||[]));}}}}else ids=[...evMap.keys()];for(const id of [...new Set(ids)]){const ev=evMap.get(id);if(!ev)continue;const doc=docMap.get(ev.document_id);const item=el('section','source-item'),meta=el('div','meta');append(meta,pill(doc?.source_kind==='case_csv'?'Данные кейса':doc?.source_kind==='bank_pdf'?'Аналитика банка':doc?.source_kind==='news'?'Первичный источник':'Материалы компании'),el('span','',ev.locator));append(item,meta,el('h3','',doc?.title||'Источник'),el('p','source-quote',ev.quote||'Числовое/графическое основание'),text(`${doc?.publisher||'Автор не указан'} · ${date(doc?.published_at)}`));if(doc?.public_url)item.append(link(doc.public_url,'Открыть оригинал'));if(doc?.source_kind==='company_upload')item.append(button('Скачать исходный файл',()=>downloadDocument(S.company.company_id,doc.document_id,doc.title),'text-button','download'));content.append(item);}if(!content.children.length)content.append(empty('Основания не найдены','Запустите разбор или откройте показатель с сохранённой ссылкой.'));$('#source-dialog').showModal();}
function showLibraryClaim(claim){return showSources(claim.evidence_ids.map(ref_id=>({kind:'evidence',ref_id})));}
function showDocumentFeatures(id){const features=S.snapshot.profile.features.filter(f=>f.source_refs.some(r=>S.snapshot.evidence.find(e=>e.evidence_id===r.ref_id)?.document_id===id));return showSources(features.flatMap(f=>f.source_refs));}
async function downloadDocument(cid,did,name){const r=await fetch(`/api/companies/${encodeURIComponent(cid)}/documents/${encodeURIComponent(did)}/download`,{headers:{'x-app-token':TOKEN}});if(!r.ok)throw new Error('access_denied');downloadBlob(await r.blob(),name);}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function downloadResult(){const data=await api(`/api/runs/${S.run.run_id}/export`);downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'business-insight.json');}
async function sendFeedback(rating){await api(`/api/runs/${S.run.run_id}/feedback`,{method:'POST',body:JSON.stringify({rating})});toast('Спасибо. Оценка сохранена вместе с этим разбором.');}
async function toggleFavorite(){const cid=S.company.company_id,path=`/api/companies/${cid}/favorites/rate_decision_20260911`;if(favorite())await api(path,{method:'DELETE'});else await api(path,{method:'PUT',body:JSON.stringify({run_id:finished()?S.run.run_id:null})});S.favorites=await api(`/api/companies/${cid}/favorites`);render();toast(favorite()?'Событие добавлено в избранное.':'Событие убрано из избранного.');}
async function startRun(){if(busyDocs()){toast('Дождитесь обновления профиля по документам.');return;}const cid=S.company.company_id;const run=await api('/api/runs',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({company_id:cid,scenario_delta_pp:S.delta,horizon_days:S.days})});if(S.company.company_id!==cid)return;S.run=run;S.runSources=null;S.view='insight';const url=new URL(location.href);url.searchParams.set('run',run.run_id);history.replaceState(null,'',url);render();pollRun();}
async function pollRun(){clearTimeout(S.runTimer);if(!S.run||!['QUEUED','RUNNING','DEFERRED_BUDGET'].includes(S.run.status))return;const id=S.run.run_id;S.runTimer=setTimeout(async()=>{try{const run=await api(`/api/runs/${id}`);if(S.run?.run_id!==id)return;S.run=run;if(S.view==='insight')render();if(!['QUEUED','RUNNING','DEFERRED_BUDGET'].includes(run.status)){S.history=await api(`/api/runs?company_id=${S.company.company_id}`);}pollRun();}catch(e){toast(message(e));}},S.run.status==='DEFERRED_BUDGET'?10000:1400);}
async function cancelRun(){S.run=await api(`/api/runs/${S.run.run_id}/cancel`,{method:'POST'});clearTimeout(S.runTimer);render();}
async function answerQuestion(valueRub){const r=S.run;S.run=await api(`/api/runs/${r.run_id}/answers`,{method:'POST',body:JSON.stringify({answer_id:crypto.randomUUID(),question_id:r.question_id,expected_version:r.version,...(valueRub===null?{skip:true}:{value_rub:valueRub})})});render();pollRun();}
async function openRun(id){const run=await api(`/api/runs/${id}`);if(S.company?.company_id!==run.company_id){const company=S.companies.find(c=>c.company_id===run.company_id)||{company_id:run.company_id,label:'Компания '+run.company_id};await selectCompany(company);}S.run=run;S.runSources=null;S.view='insight';const url=new URL(location.href);url.searchParams.set('run',id);history.replaceState(null,'',url);render();pollRun();}
async function selectCompany(company){const selection=++S.selection;clearTimeout(S.runTimer);clearTimeout(S.docsTimer);S.company=company;S.run=null;S.runSources=null;S.binding=false;S.filter='all';const cid=encodeURIComponent(company.company_id);const [snapshot,docs,connections,hist,favs]=await Promise.all([api(`/api/companies/${cid}/profile`),api(`/api/companies/${cid}/documents`),api(`/api/companies/${cid}/connections`),api(`/api/runs?company_id=${cid}`),api(`/api/companies/${cid}/favorites`)]);if(selection!==S.selection)return;S.snapshot=snapshot;S.documents=docs;S.connections=connections;S.history=hist;S.favorites=favs;localStorage.setItem('alfa-company',company.company_id);const url=new URL(location.href);url.searchParams.delete('run');history.replaceState(null,'',url);$('#company-menu').hidden=true;$('#company-toggle').setAttribute('aria-expanded','false');render();pollDocuments();}
async function uploadFiles(files){if(!S.binding){toast('Подтвердите, что документы относятся к выбранной компании.');return;}const cid=S.company.company_id;for(const file of files){if(file.size>15*1024*1024){toast('Файл '+file.name+' превышает 15 МБ.');continue;}const form=new FormData();form.append('bound_company_id',cid);form.append('file',file);try{await api(`/api/companies/${encodeURIComponent(cid)}/documents`,{method:'POST',body:form});}catch(e){toast(message(e));}}if(S.company.company_id===cid){await refreshDocuments();toast('Материалы получены. Агент начинает обработку.');}}
async function refreshDocuments(){const cid=S.company.company_id,selection=S.selection;const docs=await api(`/api/companies/${cid}/documents`);if(selection!==S.selection)return;S.documents=docs;S.snapshot=await api(`/api/companies/${cid}/profile`);render();pollDocuments();}
function pollDocuments(){clearTimeout(S.docsTimer);if(!busyDocs())return;const selection=S.selection;S.docsTimer=setTimeout(async()=>{try{const docs=await api(`/api/companies/${S.company.company_id}/documents`);if(selection!==S.selection)return;const changed=JSON.stringify(docs)!==JSON.stringify(S.documents);S.documents=docs;if(changed){S.snapshot=await api(`/api/companies/${S.company.company_id}/profile`);if(['documents','profile','home'].includes(S.view))render();}pollDocuments();}catch(e){toast(message(e));}},2200);}
async function setDocumentActive(id,active){await api(`/api/companies/${S.company.company_id}/documents/${id}/${active?'restore':'exclude'}`,{method:'POST'});await refreshDocuments();toast(active?'Документ снова участвует в профиле.':'Документ исключён из новых разборов. Прошлые результаты сохранены.');}
async function retryDocument(id){await api(`/api/companies/${S.company.company_id}/documents/${id}/retry`,{method:'POST'});await refreshDocuments();}
function companyOptions(items){const list=$('#company-options');list.replaceChildren();if(!items.length)list.append(text('Компаний не найдено. Попробуйте ID или название отрасли.'));for(const c of items){const b=button('',()=>selectCompany(c),'company-option'+(S.company?.company_id===c.company_id?' selected':''));b.setAttribute('role','option');b.setAttribute('aria-selected',String(S.company?.company_id===c.company_id));append(b,el('strong','',c.label),el('small','',c.industry||({company_upload:'Добавлена вами',synthetic_demo:'Синтетическая демонстрация'}[c.source]||'Данные кейса')));list.append(b);}}
async function initialize(){const controls=el('div','system-controls');append(controls,button('Настройки',openSettings,'source-button','settings'),button('Помощь',openHelp,'source-button','info'));$('.sidebar-footer').append(controls);document.querySelectorAll('[data-icon]').forEach(e=>e.replaceWith(icon(e.dataset.icon)));document.querySelectorAll('[data-view]').forEach(b=>{b.setAttribute('aria-label',b.textContent.replace(/\d+/g,'').trim());b.addEventListener('click',()=>go(b.dataset.view));});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));$('.brand').addEventListener('click',e=>{e.preventDefault();go('home');});$('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open));});$('#company-toggle').addEventListener('click',()=>{const menu=$('#company-menu');menu.hidden=!menu.hidden;$('#company-toggle').setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden){companyOptions(S.companies);$('#company-search').value='';$('#company-search').focus();}});document.addEventListener('click',e=>{if(!e.target.closest('.company-picker')){$('#company-menu').hidden=true;$('#company-toggle').setAttribute('aria-expanded','false');}});let searchTimer;$('#company-search').addEventListener('input',()=>{clearTimeout(searchTimer);const q=$('#company-search').value;searchTimer=setTimeout(async()=>{try{const items=await api('/api/companies?q='+encodeURIComponent(q));if($('#company-search').value===q)companyOptions(items);}catch(e){toast(message(e));}},250);});$('#role-select').addEventListener('change',()=>{S.role=$('#role-select').value;localStorage.setItem('alfa-role',S.role);render();});$('#new-company').addEventListener('click',()=>{$('#company-menu').hidden=true;$('#company-dialog').showModal();$('#company-name').focus();});$('#company-form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;try{const company=await api('/api/companies',{method:'POST',body:JSON.stringify({name:$('#company-name').value.trim()})});S.companies.unshift(company);$('#company-dialog').close();S.view='documents';await selectCompany(company);toast('Компания добавлена. Загрузите её материалы.');}catch(e){toast(message(e));}finally{submit.disabled=false;}});
 try{[S.workspace,S.companies,S.library]=await Promise.all([api('/api/workspace'),api('/api/companies'),api('/api/library')]);if(S.workspace.hosting?.notice){const note=el('div','hosting-notice',S.workspace.hosting.notice);$('.workspace-shell').insertBefore(note,$('#main'));}$('#dataset-size').textContent=S.workspace.case.available?format(S.workspace.case.company_count)+' компаний в наборе':'CSV кейса не подключены';const requestedRun=new URL(location.href).searchParams.get('run');if(requestedRun&&/^run_[a-f0-9]+$/.test(requestedRun)){await openRun(requestedRun);}else{const stored=localStorage.getItem('alfa-company');let company=S.companies.find(c=>c.company_id===stored);if(!company&&stored&&/^(U_\d+|company_[a-f0-9]+)$/.test(stored)){const more=await api('/api/companies?q='+encodeURIComponent(stored));company=more.find(c=>c.company_id===stored);}await selectCompany(company||S.companies[0]);}}catch(e){$('#main').replaceChildren(append(card(),empty('Не удалось загрузить рабочее пространство',message(e),button('Обновить страницу',()=>location.reload(),'button primary'))));}}

const QUICK_ACTIONS={documents:['Загрузить материалы','upload'],profile:['Профиль компании','building'],connections:['Платёжные связи','network'],library:['Аналитика банка','book'],history:['История разборов','clock']};
function quickPreferences(){try{const saved=JSON.parse(localStorage.getItem('alfa-quick-actions'));if(Array.isArray(saved))return saved.filter(v=>Object.hasOwn(QUICK_ACTIONS,v)).slice(0,5);}catch{}return ['documents','profile','connections'];}
function openUtility(title){let dialog=$('#utility-dialog');if(!dialog){dialog=el('dialog','company-dialog');dialog.id='utility-dialog';dialog.setAttribute('aria-labelledby','utility-title');document.body.append(dialog);}dialog.replaceChildren();const top=el('div','dialog-top'),h=el('h2','',title);h.id='utility-title';append(top,h,button('',()=>dialog.close(),'icon-button','close'));dialog.append(top);return dialog;}
function openSettings(){const d=openUtility('Быстрый доступ');d.append(text('Выберите кнопки для главного экрана. Настройка сохранится в этом браузере.'));const selected=new Set(quickPreferences()),checks=[];for(const [key,[label]] of Object.entries(QUICK_ACTIONS)){const row=el('label','binding-label'),input=el('input');input.type='checkbox';input.value=key;input.checked=selected.has(key);checks.push(input);append(row,input,el('span','',label));d.append(row);}d.append(button('Сохранить',()=>{localStorage.setItem('alfa-quick-actions',JSON.stringify(checks.filter(c=>c.checked).map(c=>c.value)));d.close();render();toast('Быстрый доступ настроен.');},'button primary'));d.showModal();}
function openHelp(){const d=openUtility('Помощь с аналитикой');d.append(text('Выберите компанию, добавьте документы и запустите разбор. Агент сопоставит источники и покажет вывод для вашей роли.'));const actions=el('div','stack utility-actions');for(const [label,view] of [['Посмотреть недостающие данные','profile'],['Загрузить документы компании','documents'],['Открыть событие и его основания','insight']])actions.append(button(label,()=>{d.close();go(view);},'button','arrow'));d.append(actions,text('Роль выбирается вручную в прототипе. В целевой интеграции она должна приходить из контура Альфа-Бизнеса.','field-help'));d.showModal();}
initialize();
